# =============================================================================
# Traefik Route Module
# =============================================================================
# Generates and syncs Traefik dynamic configuration for an app.
# Each app can self-register its routes without modifying Traefik configs.
#
# Features:
# - Auto-generates YAML config from variables
# - Syncs to Traefik LXC via file-sync module
# - Supports internal (websecure) and public (web) routes
# - Health checks, middlewares, custom options
#
# Usage:
#   module "n8n_route" {
#     source = "../../modules/traefik-route"
#
#     app_name    = "n8n"
#     backend_url = "http://192.168.1.213:5678"
#
#     internal_domain = "n8n.homelab.rambtech.dev"
#     public_domain   = ""  # Optional
#
#     traefik_host         = "192.168.1.162"
#     ssh_private_key_path = var.ssh_private_key_path
#   }
# =============================================================================

terraform {
  required_providers {
    local = {
      source = "hashicorp/local"
    }
    filesync = {
      source = "darshan-rambhia/filesync"
    }
    ansible = {
      source  = "marshallford/ansible"
      version = "~> 0.9"
    }
  }
}

# -----------------------------------------------------------------------------
# Route Configuration Templates
# -----------------------------------------------------------------------------

locals {
  # Internal route (websecure with TLS)
  internal_route = var.internal_domain != "" ? {
    rule        = "Host(`${var.internal_domain}`)"
    entryPoints = var.internal_entrypoint
    service     = var.app_name
    tls = {
      certResolver = var.cert_resolver
    }
    middlewares = var.internal_middlewares
  } : null

  # Public route (supports both HTTP and HTTPS based on entrypoint)
  public_route = var.public_domain != "" ? merge(
    {
      rule        = "Host(`${var.public_domain}`)"
      entryPoints = var.public_entrypoint
      service     = var.app_name
      middlewares = var.public_middlewares
    },
    # Add TLS config if using websecure entrypoint
    contains(var.public_entrypoint, "websecure") ? {
      tls = {
        certResolver = var.cert_resolver
      }
    } : {}
  ) : null

  # Service configuration
  service_config = {
    loadBalancer = merge(
      {
        servers = [
          { url = var.backend_url }
        ]
      },
      var.health_check != null ? { healthCheck = var.health_check } : {}
    )
  }

  # Complete Traefik config
  traefik_config = {
    http = {
      routers = merge(
        local.internal_route != null ? { "${var.app_name}" = local.internal_route } : {},
        local.public_route != null ? { "${var.app_name}-public" = local.public_route } : {}
      )
      services = {
        "${var.app_name}" = local.service_config
      }
    }
  }

  # YAML output
  config_yaml = yamlencode(local.traefik_config)

  # Target path on Traefik LXC
  remote_config_path = "/config/dynamic/${var.app_name}.yml"
}

# -----------------------------------------------------------------------------
# Write Config to Temporary File
# -----------------------------------------------------------------------------

resource "local_file" "route_config" {
  content  = local.config_yaml
  filename = "${path.module}/.tmp/${var.app_name}.yml"

  # Create directory if needed
  provisioner "local-exec" {
    command = "mkdir -p ${path.module}/.tmp"
    when    = create
  }
}

# -----------------------------------------------------------------------------
# Sync to Traefik LXC using filesync provider
# -----------------------------------------------------------------------------

resource "filesync_file" "traefik_route" {
  source      = local_file.route_config.filename
  destination = local.remote_config_path
  host        = var.traefik_host

  # SSH configuration
  ssh_key_path = var.ssh_private_key_path

  # File permissions
  owner = "root"
  group = "root"
  mode  = "0644"

  depends_on = [local_file.route_config]
}

# -----------------------------------------------------------------------------
# Reload Traefik Configuration via Ansible
# -----------------------------------------------------------------------------
# Sends SIGUSR1 to Traefik process for graceful config reload (no restart)

resource "ansible_navigator_run" "reload_traefik" {
  count = var.reload_traefik ? 1 : 0

  depends_on = [filesync_file.traefik_route]

  triggers = {
    config_hash = local_file.route_config.content
  }

  execution_environment = {
    enabled = false  # Run ansible directly on host
  }

  ansible_options = {
    private_keys = [{
      name = "homelab"
      data = file(var.ssh_private_key_path)
    }]
  }

  playbook = <<-EOT
    - name: Reload Traefik configuration
      hosts: traefik
      gather_facts: no
      vars:
        app_name: ${var.app_name}

      tasks:
        # =====================================================================
        # Graceful Reload - SIGUSR1 triggers config reload without restart
        # =====================================================================
        - name: Send SIGUSR1 to Traefik for config reload
          ansible.builtin.command:
            cmd: docker exec traefik kill -USR1 1
          register: reload_result
          failed_when: reload_result.rc != 0
          changed_when: true

        - name: Display reload status
          ansible.builtin.debug:
            msg: "Traefik configuration reloaded for {{ app_name }}"
  EOT

  inventory = yamlencode({
    traefik = {
      hosts = {
        traefik = {
          ansible_host = var.traefik_host
          ansible_user = "root"
        }
      }
    }
  })
}

# -----------------------------------------------------------------------------
# Cleanup Temp File
# -----------------------------------------------------------------------------
# Note: Temp files are left in .tmp/ directory for debugging
# They can be safely deleted manually or via .gitignore

# =============================================================================
# Common Module - Shared Data Sources and Variables
# =============================================================================
# This module provides shared resources that all apps need:
# - 1Password data sources (secrets)
# - IP registry (static IP allocation)
# - Shared variables (SSH keys, domain names, etc.)
#
# Usage in apps:
#   module "common" {
#     source = "../../modules/common"
#     ssh_private_key_path = "~/.ssh/homelab_ed25519"
#   }
#
#   # Access secrets:
#   local.op.proxmox_api_token = module.common.op.proxmox_api_token
# =============================================================================

# -----------------------------------------------------------------------------
# 1Password Data Sources
# -----------------------------------------------------------------------------

data "onepassword_vault" "homelab" {
  name = "homelab"
}

data "onepassword_item" "opentofu" {
  vault = data.onepassword_vault.homelab.uuid
  title = "opentofu"
}

data "onepassword_item" "cloudflare" {
  vault = data.onepassword_vault.homelab.uuid
  title = "Cloudflare"
}

data "onepassword_item" "grafana" {
  vault = data.onepassword_vault.homelab.uuid
  title = "grafana"
}

data "onepassword_item" "discord_webhook" {
  vault = data.onepassword_vault.homelab.uuid
  title = "discord-alertmanager-webhook"
}

# -----------------------------------------------------------------------------
# Process 1Password Items into Flat Maps
# -----------------------------------------------------------------------------

locals {
  # Extract Proxmox API token from opentofu item
  _opentofu_fields = merge([
    for s in data.onepassword_item.opentofu.section : {
      for f in s.field : f.label => f.value
    }
  ]...)

  # Extract Cloudflare tokens from Cloudflare item
  _cloudflare_fields = merge([
    for s in data.onepassword_item.cloudflare.section : {
      for f in s.field : f.label => f.value
    }
  ]...)

  # Flatten all secrets into a single map
  op = {
    # Proxmox
    proxmox_api_token = lookup(local._opentofu_fields, "proxmox_api_token", "")

    # Cloudflare
    cloudflare_tunnel_token = lookup(local._cloudflare_fields, "tunnel_token", "")
    cloudflare_api_token    = lookup(local._cloudflare_fields, "ddns_api_token", "")

    # Grafana
    grafana_admin_password = data.onepassword_item.grafana.password

    # Discord
    discord_webhook_url = data.onepassword_item.discord_webhook.credential
  }
}

# -----------------------------------------------------------------------------
# IP Registry - Static IP Allocation
# -----------------------------------------------------------------------------

locals {
  network = {
    gateway = "192.168.1.1"
    netmask = "/24"
    prefix  = "192.168.1"
  }

  ip_registry = {
    infrastructure = {
      router  = "192.168.1.1"
      proxmox = "192.168.1.215"
    }
    core = {
      network_services = "192.168.1.196"  # LXC 101 - AdGuard DNS
      traefik          = "192.168.1.162"  # LXC 200 - Reverse proxy
    }
    apps = {
      dashboards       = "192.168.1.234"  # LXC 201 - Homepage + Dashy
      authelia         = "192.168.1.225"  # LXC 202 - SSO authentication
      immich           = "192.168.1.222"  # LXC 304 - Photo management
      immich_importer  = "192.168.1.223"  # LXC 303 - Photo import
      jellyfin         = "192.168.1.226"  # LXC 401 - Media server
      media_management = "192.168.1.227"  # LXC 402 - Sonarr/Radarr/etc
      monitoring       = "192.168.1.229"  # LXC 500 - Prometheus/Grafana
      openwebui        = "192.168.1.221"  # LXC 501 - AI chat
      n8n              = "192.168.1.213"  # LXC 502 - Workflow automation
    }
    reserved = {
      # 192.168.1.200-224 reserved for manual/temporary use
    }
  }

  # Flatten all IPs into a single list
  _all_ips = concat(
    values(local.ip_registry.infrastructure),
    values(local.ip_registry.core),
    values(local.ip_registry.apps),
    values(local.ip_registry.reserved)
  )

  # Extract the last octet from each IP
  _allocated_octets = [
    for ip in local._all_ips : tonumber(split(".", ip)[3])
  ]

  # Calculate next available IP in the 150-199 range (preferred for apps)
  _primary_range = [for i in range(150, 200) : i]
  _available_primary = [
    for octet in local._primary_range : octet
    if !contains(local._allocated_octets, octet)
  ]

  next_available_ip      = length(local._available_primary) > 0 ? "${local.network.prefix}.${local._available_primary[0]}" : "NO_IPS_AVAILABLE"
  next_available_ip_cidr = "${local.next_available_ip}${local.network.netmask}"
}

# -----------------------------------------------------------------------------
# Shared Variables
# -----------------------------------------------------------------------------

variable "ssh_private_key_path" {
  description = "Path to SSH private key"
  type        = string
  default     = "~/.ssh/homelab_ed25519"
}

variable "proxmox_ssh_host" {
  description = "Proxmox SSH hostname"
  type        = string
  default     = "homelab"
}

variable "proxmox_node" {
  description = "Proxmox node name"
  type        = string
  default     = "pve"
}

variable "domain_internal" {
  description = "Internal domain for homelab services"
  type        = string
  default     = "homelab.rambtech.dev"
}

variable "domain_public" {
  description = "Public domain for external services"
  type        = string
  default     = "rambtech.dev"
}

variable "lxc_template_docker" {
  description = "Docker-ready LXC template"
  type        = string
  default     = "local:vztmpl/debian-13-docker_1.0_amd64.tar.zst"
}

# -----------------------------------------------------------------------------
# SSH Public Key Helper
# -----------------------------------------------------------------------------

locals {
  ssh_public_key = fileexists("${var.ssh_private_key_path}.pub") ? file("${var.ssh_private_key_path}.pub") : ""
}
